const coreTypingGuardRuntime = `
function syncCoreTypingGuard(){
  const guarded=document.body.classList.contains('keyboard-open');
  if(guarded)core.setAttribute('aria-disabled','true');else core.removeAttribute('aria-disabled');
}
function guardCoreWhileTyping(event){
  if(!document.body.classList.contains('keyboard-open')||!event.target.closest?.('#core'))return;
  event.preventDefault();
  event.stopImmediatePropagation();
}
document.addEventListener('pointerdown',guardCoreWhileTyping,{capture:true});
document.addEventListener('click',guardCoreWhileTyping,{capture:true});
new MutationObserver(syncCoreTypingGuard).observe(document.body,{attributes:true,attributeFilter:['class']});
syncCoreTypingGuard();
`;

